SELECT  json_build_object('nodes', coalesce(json_agg("root.f.nodes" ORDER BY "root.pg.id" ASC NULLS LAST), '[]' ), 'other', coalesce(json_agg("root.f.other" ORDER BY "root.pg.id" ASC NULLS LAST), '[]' ) ) AS "root" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.base"."id" AS "id", "_root.or.author"."author" AS "author"       ) AS "_e"      ) ) AS "root.f.nodes", row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.base"."title" AS "title", "_root.ar.other.comments"."comments" AS "comments"       ) AS "_e"      ) ) AS "root.f.other", "_root.base"."id" AS "root.pg.id" FROM  (SELECT  *  FROM "public"."article"  WHERE ('true')   ORDER BY "id" ASC NULLS LAST LIMIT 3 ) AS "_root.base" LEFT OUTER JOIN LATERAL (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.or.author.base"."name" AS "name"       ) AS "_e"      ) ) AS "author" FROM  (SELECT  *  FROM "public"."author"  WHERE (("_root.base"."author_id") = ("id"))    LIMIT 1 ) AS "_root.or.author.base"      ) AS "_root.or.author" ON ('true') LEFT OUTER JOIN LATERAL (SELECT  coalesce(json_agg("comments" ), '[]' ) AS "comments" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.ar.other.comments.base"."id" AS "id"       ) AS "_e"      ) ) AS "comments" FROM  (SELECT  *  FROM "public"."comment"  WHERE (("_root.base"."id") = ("article_id"))     ) AS "_root.ar.other.comments.base"      ) AS "_root.ar.other.comments"      ) AS "_root.ar.other.comments" ON ('true')    ORDER BY "root.pg.id" ASC NULLS LAST  ) AS "_root"
